package com.pethop.security;
import com.pethop.common.exception.ApiException; import com.pethop.user.User; import com.pethop.user.UserRepository; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.ObjectProvider; import org.springframework.mail.SimpleMailMessage; import org.springframework.mail.javamail.JavaMailSender; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class EmailVerificationService{private static final SecureRandom RANDOM=new SecureRandom();private final EmailVerificationTokenRepository tokens;private final UserRepository users;private final EmailVerificationProperties properties;private final ObjectProvider<JavaMailSender> mailers;public EmailVerificationService(EmailVerificationTokenRepository t,UserRepository u,EmailVerificationProperties p,ObjectProvider<JavaMailSender> m){tokens=t;users=u;properties=p;mailers=m;}
 @Transactional public void issue(User user){if(!properties.isEnabled()||!properties.isMailEnabled())return;JavaMailSender mailer=mailers.getIfAvailable();if(mailer==null)throw ApiException.serviceUnavailable("No fue posible enviar el correo de verificación.");Instant now=Instant.now();tokens.invalidateForUser(user.getId(),now);String raw=random();EmailVerificationToken token=new EmailVerificationToken();token.setUser(user);token.setTokenHash(hash(raw));token.setExpiresAt(now.plusSeconds(Math.max(10,properties.getTokenTtlMinutes())*60));tokens.save(token);SimpleMailMessage msg=new SimpleMailMessage();msg.setFrom(properties.getFrom());msg.setTo(user.getEmail());msg.setSubject("Confirma tu correo de PetHop");msg.setText("Confirma tu correo dentro de "+properties.getTokenTtlMinutes()+" minutos:\n\n"+properties.getFrontendUrl().replaceAll("/+$","")+"/acceso.html?mode=verify&token="+raw);try{mailer.send(msg);}catch(RuntimeException ex){throw ApiException.serviceUnavailable("No fue posible enviar el correo de verificación.");}}
 @Transactional public void confirm(String raw){if(!properties.isEnabled())throw ApiException.serviceUnavailable("La verificación de correo no está disponible.");if(raw==null||raw.isBlank())throw ApiException.badRequest("El enlace de verificación no es válido.");EmailVerificationToken token=tokens.findActive(hash(raw),Instant.now()).orElseThrow(()->ApiException.badRequest("El enlace de verificación no es válido o expiró."));User user=token.getUser();user.setEmailVerified(true);token.setUsedAt(Instant.now());users.save(user);tokens.save(token);}
 private String random(){byte[] v=new byte[32];RANDOM.nextBytes(v);return Base64.getUrlEncoder().withoutPadding().encodeToString(v);}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
